-- Errata reading for L05: Reference CKD reading with most recent = last eGFR by event_time.
WITH c AS (SELECT patient, json_extract(payload,'$.description') d, coalesce(json_extract(payload,'$.icd10'),'') i, coalesce(json_extract(payload,'$.snomed'),'') s FROM records WHERE stream='conditions'), ckd AS (SELECT DISTINCT patient FROM c WHERE (i LIKE 'N18%' OR lower(d) LIKE '%chronic kidney disease%' OR d LIKE '%CKD%' OR s='46177005' OR lower(d) LIKE '%end-stage renal disease%')), lab AS (SELECT patient, json_extract(payload,'$.value') v, row_number() OVER (PARTITION BY patient ORDER BY json_extract(payload,'$.event_date') DESC, json_extract(payload,'$.event_time') DESC, json_extract(payload,'$.record_id') DESC) rn FROM records WHERE stream='labs' AND json_extract(payload,'$.name') IN ('eGFR') AND json_extract(payload,'$.event_date') IS NOT NULL AND typeof(json_extract(payload,'$.value')) IN ('integer','real') AND coalesce(json_extract(payload,'$.result_status'),'')<>'cancelled'), last AS (SELECT patient, v FROM lab WHERE rn=1) SELECT patient AS patient_id FROM last WHERE v < 60 AND patient NOT IN (SELECT patient FROM ckd) ORDER BY 1;
